{"cmd":"python - <<'PY'
import re
from pathlib import Path

path = Path('/root/ckd_lab_data_harmonized.csv')
lines = path.read_text().splitlines()
header = lines[0].split(',')

# Check formatting for numeric columns (all except patient_id)
pattern = re.compile(r'^-?\d+\.\d{2}$')

bad = 0
for line in lines[1:]:
    parts = line.split(',')
    for idx, val in enumerate(parts):
        if header[idx] == 'patient_id':
            continue
        if not pattern.match(val):
            bad += 1
            if bad < 5:
                print('bad', header[idx], val)

print('bad_count', bad)
